// Bundle src/engine/serverEntry.ts -> api/_engine.gen.js (WS-TGBOT).
//
//   node scripts/build-engine-bundle.mjs           # build (or rebuild) it
//   node scripts/build-engine-bundle.mjs --check   # fail if it is stale/missing
//
// api/tg.js needs the REAL compiler and the REAL persona to answer in a room,
// and a Vercel function cannot import TypeScript. See src/engine/serverEntry.ts
// for why mirroring the logic was refused. This is the one generated file in
// api/, it is committed (so the deploy payload carries it exactly as tested,
// with no dependency on whether Vercel's function tracer sees files a build
// command created), and --check is what stops it drifting from its sources.
//
// It never contains a secret: serverEntry.ts pulls in persona/compiler/room
// only, none of which import api/_config.js. The check below asserts that.
import { execSync } from "node:child_process";
import { readFileSync, existsSync, writeFileSync, rmSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ENTRY = join(ROOT, "src/engine/serverEntry.ts");
const OUT = join(ROOT, "api/_engine.gen.js");
const TMP = join(ROOT, "api/_engine.gen.check.js");
const CHECK = process.argv.includes("--check");

const HEADER = `// GENERATED by scripts/build-engine-bundle.mjs from src/engine/serverEntry.ts.
// Not a source file — edit persona.ts / compiler.ts / room.ts and re-run the
// generator. \`node scripts/build-engine-bundle.mjs --check\` fails the build
// when this file no longer matches its sources.
`;

const build = (out) => {
  execSync(
    `npx esbuild ${ENTRY} --bundle --format=esm --platform=node ` +
      `--outfile=${out} --log-level=error ` +
      `--alias:@capacitor/core=${join(ROOT, "evals/stubs/capacitor.mjs")}`,
    { stdio: "inherit", cwd: ROOT },
  );
  const body = readFileSync(out, "utf8");
  // A generated file that could carry a key is a generated file that will.
  // serverEntry.ts imports nothing from api/, so this is an assertion about a
  // property that already holds, not a scrubber.
  for (const f of ["_config.js", "NEON_URL", "OPENROUTER_KEY"]) {
    if (body.includes(f)) {
      console.error(`::error::engine bundle contains ${f} — serverEntry.ts pulled in a secrets path`);
      process.exit(1);
    }
  }
  writeFileSync(out, HEADER + body);
  return HEADER + body;
};

if (CHECK) {
  if (!existsSync(OUT)) {
    console.error("::error::api/_engine.gen.js is MISSING — run node scripts/build-engine-bundle.mjs");
    process.exit(1);
  }
  const fresh = build(TMP);
  const have = readFileSync(OUT, "utf8");
  rmSync(TMP, { force: true });
  if (fresh !== have) {
    console.error(
      "::error::api/_engine.gen.js is STALE — the room path would ship a different Meera " +
        "than the one this tree tests. Run: node scripts/build-engine-bundle.mjs",
    );
    process.exit(1);
  }
  console.log(`engine bundle fresh (${have.length} bytes)`);
} else {
  const body = build(OUT);
  console.log(`wrote api/_engine.gen.js (${body.length} bytes)`);
}
